// Initialize time advancement system
const triggerData = $input.first().json;
const triggerType = $node['Time Passage Trigger'].isRunning ? 'scheduled' : 'manual';

const timeConfig = {
  advancement_id: `time_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  trigger_type: triggerType,
  timestamp: new Date().toISOString(),
  manual_settings: triggerData || {},
  advancement_parameters: {
    time_unit: triggerData.time_unit || 'hours', // minutes, hours, days, weeks, months
    time_amount: triggerData.time_amount || (triggerType === 'scheduled' ? 1 : triggerData.time_amount || 1),
    campaign_focus: triggerData.campaign_focus || 'all', // all, specific campaigns
    skip_events: triggerData.skip_events || false,
    force_events: triggerData.force_events || false,
    seasonal_transitions: triggerData.seasonal_transitions !== false // default true
  },
  world_effects: {
    natural_progression: true,
    seasonal_effects: true,
    npc_schedules: true,
    faction_activities: true,
    economic_cycles: true,
    weather_changes: true,
    random_encounters: triggerData.allow_encounters !== false
  }
};

return [{ json: timeConfig }];

// Process time state and calculate time advancement
const timeConfig = $input.first().json;
const campaigns = $input.last().json.results || [];

const processedCampaigns = campaigns.map(campaign => {
  const { campaignId, worldState, timeData, lastUpdate, campaignSettings } = campaign;

  // Calculate time advancement for this campaign
  const currentTime = timeData ? parseTimeData(timeData) : initializeDefaultTime();
  const advancementAmount = calculateAdvancementAmount(timeConfig.advancement_parameters, campaignSettings);
  const newTime = advanceTime(currentTime, advancementAmount);

  // Analyze time-based changes
  const timeAnalysis = analyzeTimeChanges(currentTime, newTime, worldState, advancementAmount);

  // Check for significant time events
  const timeEvents = identifyTimeEvents(currentTime, newTime, worldState, timeAnalysis);

  return {
    campaignId,
    current_time: currentTime,
    new_time: newTime,
    advancement_amount: advancementAmount,
    time_analysis: timeAnalysis,
    time_events: timeEvents,
    campaign_settings: campaignSettings || {},
    world_state: worldState || {},
    last_update: lastUpdate
  };
});

// Sort campaigns by time sensitivity
processedCampaigns.sort((a, b) => {
  const aPriority = calculateTimePriority(a);
  const bPriority = calculateTimePriority(b);
  return bPriority - aPriority;
});

function parseTimeData(timeData) {
  return {
    current_date: new Date(timeData.current_date),
    current_time: timeData.current_time || { hours: 12, minutes: 0 },
    day_count: timeData.day_count || 1,
    week_count: timeData.week_count || 1,
    month_count: timeData.month_count || 1,
    year_count: timeData.year_count || 1,
    current_season: timeData.current_season || 'spring',
    day_of_week: timeData.day_of_week || 1,
    time_of_day: timeData.time_of_day || 'day',
    weather: timeData.weather || 'clear',
    moon_phase: timeData.moon_phase || 'new'
  };
}

function initializeDefaultTime() {
  const now = new Date();
  return {
    current_date: now,
    current_time: { hours: now.getHours(), minutes: now.getMinutes() },
    day_count: 1,
    week_count: 1,
    month_count: 1,
    year_count: 1,
    current_season: determineSeason(now),
    day_of_week: now.getDay() || 1,
    time_of_day: determineTimeOfDay(now.getHours()),
    weather: 'clear',
    moon_phase: calculateMoonPhase(now)
  };
}

function calculateAdvancementAmount(parameters, campaignSettings) {
  const { time_unit, time_amount } = parameters;

  // Check for campaign-specific time scaling
  const timeScale = campaignSettings?.time_scale || 1.0;
  const adjustedAmount = time_amount * timeScale;

  return {
    unit: time_unit,
    amount: adjustedAmount,
    in_minutes: convertToMinutes(time_unit, adjustedAmount),
    scaled: timeScale !== 1.0
  };
}

function convertToMinutes(unit, amount) {
  const conversions = {
    'minutes': amount,
    'hours': amount * 60,
    'days': amount * 60 * 24,
    'weeks': amount * 60 * 24 * 7,
    'months': amount * 60 * 24 * 30 // Approximate
  };

  return conversions[unit] || amount;
}

function advanceTime(currentTime, advancementAmount) {
  const newDate = new Date(currentTime.current_date);
  const currentMinutes = currentTime.current_time.hours * 60 + currentTime.current_time.minutes;
  const totalMinutes = currentMinutes + advancementAmount.in_minutes;

  // Calculate new date and time
  newDate.setTime(newDate.getTime() + advancementAmount.in_minutes * 60 * 1000);

  const newTime = {
    current_date: newDate,
    current_time: {
      hours: newDate.getHours(),
      minutes: newDate.getMinutes()
    },
    day_count: currentTime.day_count + Math.floor(advancementAmount.in_minutes / (60 * 24)),
    week_count: currentTime.week_count + Math.floor(advancementAmount.in_minutes / (60 * 24 * 7)),
    month_count: currentTime.month_count + Math.floor(advancementAmount.in_minutes / (60 * 24 * 30)),
    year_count: currentTime.year_count + Math.floor(advancementAmount.in_minutes / (60 * 24 * 365)),
    current_season: determineSeason(newDate),
    day_of_week: newDate.getDay() || 1,
    time_of_day: determineTimeOfDay(newDate.getHours()),
    weather: currentTime.weather, // Will be updated by weather system
    moon_phase: calculateMoonPhase(newDate)
  };

  return newTime;
}

function determineSeason(date) {
  const month = date.getMonth(); // 0-11

  if (month >= 2 && month <= 4) return 'spring';
  if (month >= 5 && month <= 7) return 'summer';
  if (month >= 8 && month <= 10) return 'autumn';
  return 'winter';
}

function determineTimeOfDay(hour) {
  if (hour >= 6 && hour < 12) return 'morning';
  if (hour >= 12 && hour < 17) return 'afternoon';
  if (hour >= 17 && hour < 21) return 'evening';
  if (hour >= 21 || hour < 6) return 'night';
  return 'day';
}

function calculateMoonPhase(date) {
  // Simple moon phase calculation
  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();

  let c, e, jd, b;

  if (month < 3) {
    year--;
    month += 12;
  }

  c = 365.25 * year;
  e = 30.6 * month;
  jd = c + e + day - 694039.09; // JD is Julian date
  jd /= 29.5305882; // Divide by the moon cycle
  1; // Remove integer part
  jd = Math.round(jd); // Round to nearest integer

  b = jd / 8;
  jd -= b;
  b = jd / 4;
  jd -= b;

  const phases = ['new', 'waxing_crescent', 'first_quarter', 'waxing_gibbous', 'full', 'waning_gibbous', 'last_quarter', 'waning_crescent'];
  return phases[Math.floor(jd * 8)] || 'new';
}

function analyzeTimeChanges(oldTime, newTime, worldState, advancementAmount) {
  const analysis = {
    significant_changes: [],
    seasonal_transitions: [],
    time_of_day_changes: [],
    date_milestones: [],
    environmental_factors: [],
    social_factors: [],
    magical_factors: []
  };

  // Check for seasonal transition
  if (oldTime.current_season !== newTime.current_season) {
    analysis.seasonal_transitions.push({
      from: oldTime.current_season,
      to: newTime.current_season,
      transition_type: 'seasonal_change',
      impact_level: 'major'
    });
  }

  // Check for time of day transitions
  if (oldTime.time_of_day !== newTime.time_of_day) {
    analysis.time_of_day_changes.push({
      from: oldTime.time_of_day,
      to: newTime.time_of_day,
      transition_type: 'time_of_day_change',
      impact_level: 'minor'
    });
  }

  // Check for date milestones
  if (newTime.day_count % 7 === 0) {
    analysis.date_milestones.push({
      type: 'weekly',
      week_number: newTime.week_count,
      description: `Week ${newTime.week_count} begins`
    });
  }

  if (newTime.day_count % 30 === 0) {
    analysis.date_milestones.push({
      type: 'monthly',
      month_number: newTime.month_count,
      description: `Month ${newTime.month_count} begins`
    });
  }

  if (newTime.day_count % 365 === 0) {
    analysis.date_milestones.push({
      type: 'yearly',
      year_number: newTime.year_count,
      description: `Year ${newTime.year_count} begins`
    });
  }

  // Environmental factors based on time
  analysis.environmental_factors = generateEnvironmentalFactors(newTime, advancementAmount);

  // Social factors based on time
  analysis.social_factors = generateSocialFactors(newTime, worldState);

  // Magical factors based on time
  analysis.magical_factors = generateMagicalFactors(newTime, worldState);

  return analysis;
}

function generateEnvironmentalFactors(newTime, advancementAmount) {
  const factors = [];

  // Weather changes based on time advancement
  if (advancementAmount.in_minutes >= 60) {
    factors.push({
      type: 'weather_change',
      probability: 0.3,
      description: 'Weather conditions may change',
      impact: 'environmental'
    });
  }

  // Seasonal environmental effects
  const seasonalEffects = {
    'spring': [
      { type: 'plant_growth', probability: 0.7, description: 'Plants begin to grow and bloom' },
      { type: 'animal_migration', probability: 0.5, description: 'Animals migrate back to the region' },
      { type: 'rain_increase', probability: 0.6, description: 'Increased rainfall' }
    ],
    'summer': [
      { type: 'heat_waves', probability: 0.4, description: 'Periods of extreme heat' },
      { type: 'drought_conditions', probability: 0.3, description: 'Possible drought conditions' },
      { type: 'peak_activity', probability: 0.8, description: 'Peak plant and animal activity' }
    ],
    'autumn': [
      { type: 'harvest_season', probability: 0.9, description: 'Harvest season begins' },
      { type: 'leaf_fall', probability: 0.8, description: 'Trees begin to lose their leaves' },
      { type: 'animal_preparation', probability: 0.7, description: 'Animals prepare for winter' }
    ],
    'winter': [
      { type: 'snowfall', probability: 0.6, description: 'Snow becomes more likely' },
      { type: 'reduced_activity', probability: 0.8, description: 'Natural activity decreases' },
      { type: 'cold_stress', probability: 0.5, description: 'Cold weather affects creatures' }
    ]
  };

  factors.push(...(seasonalEffects[newTime.current_season] || []));

  // Time of day effects
  const timeOfDayEffects = {
    'morning': [
      { type: 'dew_formation', probability: 0.7, description: 'Morning dew forms on surfaces' },
      { type: 'increased_visibility', probability: 0.9, description: 'Visibility improves with daylight' }
    ],
    'afternoon': [
      { type: 'peak_heat', probability: 0.8, description: 'Temperatures reach daily peak' },
      { type: 'shadow_changes', probability: 1.0, description: 'Shadows shift throughout afternoon' }
    ],
    'evening': [
      { type: 'golden_hour', probability: 0.9, description: 'Golden hour lighting conditions' },
      { type: 'temperature_drop', probability: 0.8, description: 'Temperatures begin to drop' }
    ],
    'night': [
      { type: 'reduced_visibility', probability: 1.0, description: 'Visibility significantly reduced' },
      { type: 'nocturnal_activity', probability: 0.7, description: 'Nocturnal creatures become active' }
    ]
  };

  factors.push(...(timeOfDayEffects[newTime.time_of_day] || []));

  return factors;
}

function generateSocialFactors(newTime, worldState) {
  const factors = [];

  // Time of day social effects
  const timeSocialEffects = {
    'morning': [
      { type: 'market_opening', probability: 0.9, description: 'Markets and shops open for business' },
      { type: 'work_day_start', probability: 0.8, description: 'Most workers begin their day' }
    ],
    'afternoon': [
      { type: 'peak_business', probability: 0.9, description: 'Peak business and commercial activity' },
      { type: 'social_gatherings', probability: 0.6, description: 'People gather for midday meals and socializing' }
    ],
    'evening': [
      { type: 'tavern_activity', probability: 0.9, description: 'Taverns and entertainment venues become busy' },
      { type: 'family_time', probability: 0.7, description: 'Families gather for evening meals' }
    ],
    'night': [
      { type: 'curfew_hours', probability: 0.6, description: 'Some settlements may enforce curfews' },
      { type: 'night_watch', probability: 0.8, description: 'City guards and night patrols become active' }
    ]
  };

  factors.push(...(timeSocialEffects[newTime.time_of_day] || []));

  // Day of week effects
  const dayOfWeekEffects = [
    { type: 'weekend_preparation', day: 5, probability: 0.7, description: 'People prepare for weekend' },
    { type: 'weekend_leisure', day: 6, probability: 0.8, description: 'Weekend leisure activities increase' },
    { type: 'weekend_leisure', day: 0, probability: 0.8, description: 'Weekend leisure activities continue' },
    { type: 'week_beginning', day: 1, probability: 0.7, description: 'People return to work and routines' }
  ];

  const dayEffect = dayOfWeekEffects.find(effect => effect.day === newTime.day_of_week);
  if (dayEffect) {
    factors.push({
      type: dayEffect.type,
      probability: dayEffect.probability,
      description: dayEffect.description
    });
  }

  return factors;
}

function generateMagicalFactors(newTime, worldState) {
  const factors = [];

  // Moon phase magical effects
  const moonEffects = {
    'new': [
      { type: 'divination_difficulty', probability: 0.6, description: 'Divination magic becomes more difficult' },
      { type: 'shadow_magic_boost', probability: 0.7, description: 'Shadow and illusion magic enhanced' }
    ],
    'full': [
      { type: 'lycanthrope_activity', probability: 0.9, description: 'Lycanthropes become more active' },
      { type: 'divination_power', probability: 0.8, description: 'Divination and scrying magic enhanced' },
      { type: 'wild_magic_increase', probability: 0.5, description: 'Wild magic surges more likely' }
    ],
    'first_quarter': [
      { type: 'creation_magic', probability: 0.6, description: 'Creation and growth magic favored' }
    ],
    'last_quarter': [
      { type: 'destruction_magic', probability: 0.6, description: 'Destruction and banishing magic favored' }
    ]
  };

  factors.push(...(moonEffects[newTime.moon_phase] || []));

  // Time of day magical effects
  const timeMagicEffects = {
    'night': [
      { type: 'shadow_magic_amplified', probability: 0.7, description: 'Shadow magic amplified at night' },
      { type: 'necromancy_power', probability: 0.6, description: 'Necromantic power increases after dark' }
    ],
    'day': [
      { type: 'light_magic_amplified', probability: 0.7, description: 'Light and fire magic amplified by daylight' },
      { type: 'healing_enhanced', probability: 0.5, description: 'Healing magic slightly enhanced during day' }
    ]
  };

  const timeEffect = timeMagicEffects[newTime.time_of_day === 'night' ? 'night' : 'day'];
  if (timeEffect) {
    factors.push(...timeEffect);
  }

  return factors;
}

function identifyTimeEvents(oldTime, newTime, worldState, timeAnalysis) {
  const events = [];

  // Seasonal transition events
  timeAnalysis.seasonal_transitions.forEach(transition => {
    events.push({
      id: `season_transition_${Date.now()}`,
      type: 'seasonal_transition',
      subtype: transition.transition_type,
      from_season: transition.from,
      to_season: transition.to,
      description: generateSeasonalTransitionDescription(transition.from, transition.to),
      impact_level: transition.impact_level,
      environmental_effects: generateSeasonalEffects(transition.to),
      social_effects: generateSeasonalSocialEffects(transition.from, transition.to),
      economic_effects: generateSeasonalEconomicEffects(transition.from, transition.to),
      player_hooks: generateSeasonalPlayerHooks(transition.from, transition.to),
      timestamp: new Date().toISOString()
    });
  });

  // Date milestone events
  timeAnalysis.date_milestones.forEach(milestone => {
    events.push({
      id: `${milestone.type}_milestone_${Date.now()}`,
      type: 'date_milestone',
      subtype: milestone.type,
      description: milestone.description,
      impact_level: 'minor',
      social_effects: generateMilestoneSocialEffects(milestone.type),
      player_hooks: generateMilestonePlayerHooks(milestone.type),
      timestamp: new Date().toISOString()
    });
  });

  // Weather events
  if (Math.random() < 0.2) {
    events.push(generateWeatherEvent(newTime, worldState));
  }

  // Random encounter possibilities
  if (worldState.encounter_settings?.random_encounters !== false && Math.random() < 0.15) {
    events.push(generateTimeBasedEncounter(newTime, worldState));
  }

  // NPC schedule events
  events.push(...generateNPCScheduleEvents(newTime, worldState));

  return events;
}

function generateSeasonalTransitionDescription(from, to) {
  const transitions = {
    'spring_to_summer': 'The warmth of summer begins to take hold, days grow longer and nature reaches its peak vitality',
    'summer_to_autumn': 'The first signs of autumn appear as the air cools and leaves begin to change color',
    'autumn_to_winter': 'Winter\'s chill arrives with shorter days and the promise of snow',
    'winter_to_spring': 'Spring emerges with new life as the world awakens from winter\'s slumber'
  };

  return transitions[`${from}_to_${to}`] || `The seasons transition from ${from} to ${to}`;
}

function generateSeasonalEffects(season) {
  const effects = {
    'spring': ['increased_plant_growth', 'animal_migration', 'mild_temperatures', 'rain_showers'],
    'summer': ['hot_temperatures', 'peak_vegetation', 'long_daylight', 'thunderstorms'],
    'autumn': ['falling_leaves', 'harvest_time', 'cooling_temperatures', 'migration_preparation'],
    'winter': ['snow_fall', 'cold_temperatures', 'short_daylight', 'dormant_nature']
  };

  return effects[season] || [];
}

function generateSeasonalSocialEffects(from, to) {
  const socialEffects = {
    'spring_to_summer': ['outdoor_activities_increase', 'festival_season_begins', 'trade_routes_open'],
    'summer_to_autumn': ['harvest_festivals', 'winter_preparations', 'trade_slowdown'],
    'autumn_to_winter': ['indoor_activities', 'winter_storage', 'community_gatherings'],
    'winter_to_spring': ['spring_festivals', 'planting_season', 'renewed_activity']
  };

  return socialEffects[`${from}_to_${to}`] || ['seasonal_routine_changes'];
}

function generateSeasonalEconomicEffects(from, to) {
  const economicEffects = {
    'spring_to_summer': ['construction_boom', 'trade_peak', 'tourism_increase'],
    'summer_to_autumn': ['harvest_economy', 'preservation_trade', 'equipment_sales'],
    'autumn_to_winter': ['winter_supply_demand', 'heating_costs', 'reduced_trade'],
    'winter_to_spring': ['seed_demand', 'construction_planning', 'equipment_repair']
  };

  return economicEffects[`${from}_to_${to}`] || ['seasonal_economic_shifts'];
}

function generateSeasonalPlayerHooks(from, to) {
  const hooks = {
    'spring_to_summer': ['outdoor_adventures', 'festival_attendance', 'long_distance_travel'],
    'summer_to_autumn': ['harvest_work', 'winter_preparation', 'community_events'],
    'autumn_to_winter': ['winter_survival', 'indoor_activities', 'monster_migrations'],
    'winter_to_spring': ['spring_festivals', 'exploration', 'renewed_conflicts']
  };

  return hooks[`${from}_to_${to}`] || ['seasonal_adventures'];
}

function generateMilestoneSocialEffects(milestoneType) {
  const effects = {
    'weekly': ['market_day', 'religious_services', 'community_meetings'],
    'monthly': ['tax_collection', 'guild_meetings', 'long_term_planning'],
    'yearly': ['festivals', 'elections', 'major_celebrations']
  };

  return effects[milestoneType] || ['routine_social_activities'];
}

function generateMilestonePlayerHooks(milestoneType) {
  const hooks = {
    'weekly': ['market_opportunities', 'information_gathering', 'social_networking'],
    'monthly': ['guild_quests', 'political_events', 'long_term_contracts'],
    'yearly': ['major_festivals', 'tournaments', 'special_events']
  };

  return hooks[milestoneType] || ['time_based_opportunities'];
}

function generateWeatherEvent(newTime, worldState) {
  const weatherTypes = {
    'spring': ['rain_shower', 'thunderstorm', 'clear_skies', 'light_wind'],
    'summer': ['heat_wave', 'thunderstorm', 'clear_hot', 'hazy'],
    'autumn': ['rain_storm', 'fog', 'clear_cool', 'strong_winds'],
    'winter': ['snowfall', 'blizzard', 'clear_cold', 'ice_storm']
  };

  const seasonWeather = weatherTypes[newTime.current_season] || ['clear'];
  const weather = seasonWeather[Math.floor(Math.random() * seasonWeather.length)];

  return {
    id: `weather_${Date.now()}`,
    type: 'weather_event',
    subtype: weather,
    description: `The weather changes to ${weather.replace('_', ' ')}`,
    impact_level: 'minor',
    environmental_effects: generateWeatherEffects(weather),
    travel_effects: generateWeatherTravelEffects(weather),
    visibility_effects: generateWeatherVisibilityEffects(weather),
    player_hooks: generateWeatherPlayerHooks(weather),
    duration: calculateWeatherDuration(weather),
    timestamp: new Date().toISOString()
  };
}

function generateWeatherEffects(weather) {
  const effects = {
    'rain_shower': ['wet_conditions', 'reduced_visibility', 'plant_growth'],
    'thunderstorm': ['lightning_risk', 'heavy_rain', 'strong_winds'],
    'heat_wave': ['dehydration_risk', 'heat_exhaustion', 'fire_danger'],
    'snowfall': ['cold_exposure', 'travel_difficulty', 'beauty'],
    'blizzard': ['whiteout_conditions', 'extreme_cold', 'survival_challenge'],
    'fog': ['severely_reduced_visibility', 'eerie_atmosphere', 'navigation_difficulty'],
    'clear_skies': ['excellent_visibility', 'pleasant_conditions', 'travel_favorable']
  };

  return effects[weather] || ['weather_change'];
}

function generateWeatherTravelEffects(weather) {
  const effects = {
    'rain_shower': { speed_penalty: 0.2, difficulty_increase: 0.1 },
    'thunderstorm': { speed_penalty: 0.5, difficulty_increase: 0.3 },
    'heat_wave': { speed_penalty: 0.3, difficulty_increase: 0.2 },
    'snowfall': { speed_penalty: 0.4, difficulty_increase: 0.25 },
    'blizzard': { speed_penalty: 0.8, difficulty_increase: 0.6 },
    'fog': { speed_penalty: 0.3, difficulty_increase: 0.2 },
    'clear_skies': { speed_bonus: 0.1, difficulty_decrease: 0.05 }
  };

  return effects[weather] || {};
}

function generateWeatherVisibilityEffects(weather) {
  const effects = {
    'rain_shower': { visibility_penalty: 0.2 },
    'thunderstorm': { visibility_penalty: 0.5 },
    'fog': { visibility_penalty: 0.8 },
    'blizzard': { visibility_penalty: 0.9 },
    'clear_skies': { visibility_bonus: 0.1 }
  };

  return effects[weather] || {};
}

function generateWeatherPlayerHooks(weather) {
  const hooks = {
    'rain_shower': ['shelter_seeking', 'indoor_activities', 'puddle_jumping'],
    'thunderstorm': ['lightning_magic_enhanced', 'shelter_quests', 'storm_related_encounters'],
    'heat_wave': ['cooling_magic', 'water_sources', 'heat_protection'],
    'snowfall': ['winter_sports', 'tracking_difficulties', 'shelter_needs'],
    'blizzard': ['survival_challenges', 'shelter_quests', 'extreme_weather_adventures'],
    'fog': ['mystery_encounters', 'navigation_challenges', 'ambush_opportunities'],
    'clear_skies': ['travel_favorable', 'outdoor_activities', 'visibility_bonuses']
  };

  return hooks[weather] || ['weather_adaptation'];
}

function calculateWeatherDuration(weather) {
  const durations = {
    'rain_shower': '1-3 hours',
    'thunderstorm': '2-6 hours',
    'heat_wave': '1-3 days',
    'snowfall': '4-12 hours',
    'blizzard': '6-24 hours',
    'fog': '2-8 hours',
    'clear_skies': '1-3 days'
  };

  return durations[weather] || 'few hours';
}

function generateTimeBasedEncounter(newTime, worldState) {
  const encounterTypes = {
    'morning': ['traveling_merchants', 'early_risers', 'dawn_patrols'],
    'afternoon': ['bandit_ambush', 'traveling_nobles', 'merchant_caravans'],
    'evening': ['night_creatures', 'drunk_patrons', 'city_watch'],
    'night': ['nocturnal_predators', 'shady_dealers', 'supernatural_beings']
  };

  const timeEncounters = encounterTypes[newTime.time_of_day] || ['random_encounter'];
  const encounter = timeEncounters[Math.floor(Math.random() * timeEncounters.length)];

  return {
    id: `time_encounter_${Date.now()}`,
    type: 'time_based_encounter',
    subtype: encounter,
    description: `A ${encounter.replace('_', ' ')} is encountered due to the time of day`,
    impact_level: 'moderate',
    encounter_details: generateEncounterDetails(encounter, newTime),
    player_hooks: generateEncounterPlayerHooks(encounter),
    difficulty_modifier: calculateEncounterDifficultyModifier(newTime, encounter),
    timestamp: new Date().toISOString()
  };
}

function generateEncounterDetails(encounter, timeContext) {
  const details = {
    'traveling_merchants': {
      count: Math.floor(Math.random() * 3) + 1,
      goods: ['general_merchandise', 'specialty_items'],
      attitude: 'friendly',
      interaction_type: 'trade'
    },
    'bandit_ambush': {
      count: Math.floor(Math.random() * 4) + 2,
      motivation: 'robbery',
      tactics: 'ambush',
      interaction_type: 'combat'
    },
    'nocturnal_predators': {
      creatures: ['wolves', 'bears', 'magical_beasts'],
      motivation: 'hunting',
      hostility_level: 'high',
      interaction_type: 'combat_or_flee'
    },
    'shady_dealers': {
      specialty: ['illegal_goods', 'information', 'services'],
      location: 'shadows_or_back_rooms',
      risk_level: 'variable',
      interaction_type: 'negotiation'
    }
  };

  return details[encounter] || { interaction_type: 'roleplay' };
}

function generateEncounterPlayerHooks(encounter) {
  const hooks = {
    'traveling_merchants': ['trading_opportunities', 'information_gathering', 'employment'],
    'bandit_ambush': ['combat_challenge', 'morality_choices', 'treasure_recovery'],
    'nocturnal_predators': ['survival_challenge', 'combat_encounter', 'tracking_opportunity'],
    'shady_dealers': ['illegal_acquisition', 'information_purchase', 'risk_vs_reward']
  };

  return hooks[encounter] || ['roleplay_opportunity'];
}

function calculateEncounterDifficultyModifier(timeContext, encounter) {
  let modifier = 0;

  // Time of day modifiers
  if (timeContext.time_of_day === 'night') {
    modifier += 0.2; // Night encounters are harder
  }

  // Weather modifiers would be added here if weather was tracked

  // Encounter type modifiers
  const encounterModifiers = {
    'bandit_ambush': 0.1,
    'nocturnal_predators': 0.15,
    'supernatural_beings': 0.2
  };

  modifier += encounterModifiers[encounter] || 0;

  return modifier;
}

function generateNPCScheduleEvents(newTime, worldState) {
  const events = [];

  if (worldState.npcs) {
    worldState.npcs.forEach(npc => {
      const scheduleEvent = generateNPCScheduleEvent(npc, newTime);
      if (scheduleEvent) {
        events.push(scheduleEvent);
      }
    });
  }

  return events;
}

function generateNPCScheduleEvent(npc, timeContext) {
  // Only create events for important NPCs or those with specific schedules
  if (!npc.important && !npc.schedule) {
    return null;
  }

  const scheduleActivities = {
    'morning': ['shop_opening', 'work_start', 'patrol_begin'],
    'afternoon': ['busy_work', 'customer_service', 'meetings'],
    'evening': ['shop_closing', 'leisure_time', 'socializing'],
    'night': ['sleeping', 'night_work', 'guard_duty']
  };

  const activities = scheduleActivities[timeContext.time_of_day] || ['routine_activity'];
  const activity = activities[Math.floor(Math.random() * activities.length)];

  return {
    id: `npc_schedule_${npc.id}_${Date.now()}`,
    type: 'npc_schedule_event',
    npc_id: npc.id,
    npc_name: npc.name,
    activity,
    location: npc.location || 'unknown',
    description: `${npc.name} is ${activity.replace('_', ' ')}`,
    impact_level: 'trivial',
    player_relevant: npc.important || Math.random() < 0.1,
    timestamp: new Date().toISOString()
  };
}

function calculateTimePriority(campaign) {
  let priority = 5;

  // Higher priority for campaigns with more time-sensitive elements
  if (campaign.world_state?.quests) {
    const timeSensitiveQuests = campaign.world_state.quests.filter(quest => 
      quest.time_limit && quest.time_limit > 0
    );
    priority += timeSensitiveQuests.length * 2;
  }

  // Higher priority for campaigns with active time-based events
  if (campaign.time_events && campaign.time_events.length > 0) {
    priority += campaign.time_events.length;
  }

  // Higher priority for campaigns with complex schedules
  if (campaign.world_state?.npcs && campaign.world_state.npcs.length > 20) {
    priority += 3;
  }

  return Math.min(priority, 10);
}

return [{
  json: {
    ...timeConfig,
    campaigns: processedCampaigns,
    total_campaigns: processedCampaigns.length,
    processing_timestamp: new Date().toISOString()
  }
}];

// Generate time-based narrative events for campaign
const timeConfig = $input.first().json;
const campaign = $input.first().json.campaigns[$input.first().json.currentCampaignIndex || 0];

const { campaignId, current_time, new_time, time_events, time_analysis } = campaign;

// Combine time events and analysis into narrative structure
const narrativeEvents = time_events.map(event => ({
  ...event,
  time_context: {
    advancement: campaign.advancement_amount,
    old_time: current_time,
    new_time: new_time,
    time_changes: time_analysis
  },
  campaign_context: {
    id: campaignId,
    world_state: campaign.world_state,
    settings: campaign.campaign_settings
  }
}));

// Generate additional atmospheric events based on time changes
const atmosphericEvents = generateAtmosphericEvents(new_time, time_analysis, campaign.world_state);

// Generate player-relevant time notifications
const playerNotifications = generatePlayerTimeNotifications(narrativeEvents, atmosphericEvents, new_time);

// Generate time advancement consequences
const timeConsequences = generateTimeConsequences(new_time, time_analysis, campaign.world_state);

function generateAtmosphericEvents(newTime, timeAnalysis, worldState) {
  const events = [];

  // Environmental descriptions based on time and season
  const seasonalDescriptions = {
    'spring': {
      'morning': 'Dew glistens on new growth as birdsong fills the air',
      'afternoon': 'Warm sunshine encourages flowers to open their petals',
