// Process DeepSeek narratives and prepare time state updates
const timeData = $input.first().json;
const deepseekResponse = $input.last().json;

let narrativeData = {};
try {
  const content = deepseekResponse.choices[0].message.content;
  narrativeData = JSON.parse(content);
} catch (error) {
  console.error('Failed to parse DeepSeek time narrative:', error);
  narrativeData = {
    literary_description: 'Time passes in the world, bringing changes both subtle and profound.',
    character_perceptions: 'Different characters notice different aspects of the passing time.',
    adventure_hints: 'New opportunities may arise with the changing time.',
    world_reactions: 'The world and its inhabitants adapt to the flow of time.',
    foreshadowing: 'Further changes may come with continued time progression.'
  };
}

// Enrich time events with literary descriptions
const enrichedEvents = timeData.narrative_events.map((event, index) => {
  const eventNarrative = narrativeData.events?.[index] || narrativeData;

  return {
    ...event,
    literary_description: eventNarrative.literary_description || event.description,
    character_perceptions: eventNarrative.character_perceptions || 'Various characters notice this change.',
    adventure_hints: eventNarrative.adventure_hints || 'This may present new opportunities.',
    world_reactions: eventNarrative.world_reactions || 'The world responds to this change.',
    foreshadowing: eventNarrative.foreshadowing || 'Further developments may follow.',
    processed: true
  };
});

// Enrich atmospheric events
const enrichedAtmosphericEvents = timeData.atmospheric_events.map(event => ({
  ...event,
  literary_description: narrativeData.literary_description || event.description,
  character_perceptions: narrativeData.character_perceptions || 'This affects different characters in various ways.',
  processed: true
}));

// Prepare time state updates
const timeStateUpdates = {
  new_time: timeData.time_advancement.new_time,
  time_passed: timeData.time_advancement.advancement,
  time_analysis: timeData.time_advancement.time_analysis,
  last_update: new Date().toISOString(),
  narrative_summary: narrativeData.literary_description || 'Time progresses naturally',
  significant_events: enrichedEvents.filter(e => e.impact_level === 'major'),
  player_notifications: timeData.player_notifications,
  consequences: timeData.time_consequences
};

// Generate time advancement summary
const timeSummary = generateTimeSummary(timeData, enrichedEvents, enrichedAtmosphericEvents, narrativeData);

function generateTimeSummary(timeData, events, atmosphericEvents, narrativeData) {
  return {
    time_advancement_id: `time_${timeData.campaignId}_${Date.now()}`,
    campaign_id: timeData.campaignId,
    processing_time: new Date().toISOString(),
    time_changes: {
      old_time: {
        date: timeData.time_advancement.old_time.current_date.toISOString().split('T')[0],
        time: `${timeData.time_advancement.old_time.current_time.hours}:${String(timeData.time_advancement.old_time.current_time.minutes).padStart(2, '0')}`,
        season: timeData.time_advancement.old_time.current_season,
        day_of_week: timeData.time_advancement.old_time.day_of_week,
        time_of_day: timeData.time_advancement.old_time.time_of_day
      },
      new_time: {
        date: timeData.time_advancement.new_time.current_date.toISOString().split('T')[0],
        time: `${timeData.time_advancement.new_time.current_time.hours}:${String(timeData.time_advancement.new_time.current_time.minutes).padStart(2, '0')}`,
        season: timeData.time_advancement.new_time.current_season,
        day_of_week: timeData.time_advancement.new_time.day_of_week,
        time_of_day: timeData.time_advancement.new_time.time_of_day,
        day_count: timeData.time_advancement.new_time.day_count
      },
      advancement: {
        amount: timeData.time_advancement.advancement.amount,
        unit: timeData.time_advancement.advancement.unit,
        minutes_passed: timeData.time_advancement.advancement.in_minutes
      }
    },
    events_summary: {
      total_events: events.length + atmosphericEvents.length,
      narrative_events: events.length,
      atmospheric_events: atmosphericEvents.length,
      major_events: events.filter(e => e.impact_level === 'major').length,
      seasonal_transitions: events.filter(e => e.type === 'seasonal_transition').length,
      weather_events: events.filter(e => e.type === 'weather_event').length,
      time_based_encounters: events.filter(e => e.type === 'time_based_encounter').length
    },
    narrative_summary: {
      literary_description: narrativeData.literary_description,
      character_perceptions: narrativeData.character_perceptions,
      adventure_hints: narrativeData.adventure_hints,
      world_reactions: narrativeData.world_reactions,
      foreshadowing: narrativeData.foreshadowing
    },
    player_impact: {
      notifications: timeData.player_notifications.length,
      actionable_events: events.filter(e => e.player_actionable).length,
      adventure_opportunities: events.filter(e => e.player_hooks && e.player_hooks.length > 0).length,
      atmospheric_changes: atmosphericEvents.length
    },
    world_state_impact: {
      npc_schedule_changes: events.filter(e => e.type === 'npc_schedule_event').length,
      environmental_effects: timeData.time_advancement.time_analysis.environmental_factors.length,
      social_factors: timeData.time_advancement.time_analysis.social_factors.length,
      magical_factors: timeData.time_advancement.time_analysis.magical_factors.length
    },
    next_time_milestones: calculateNextTimeMilestones(timeData.time_advancement.new_time)
  };
}

function calculateNextTimeMilestones(newTime) {
  const milestones = [];

  // Next time of day change
  const nextTimeOfDay = getNextTimeOfDay(newTime.time_of_day);
  const hoursUntilNext = getHoursUntilNextTimeOfDay(newTime.current_time.hours, newTime.time_of_day);

  milestones.push({
    type: 'time_of_day_change',
    description: `Transition to ${nextTimeOfDay}`,
    time_until: `${hoursUntilNext} hours`,
    impact_level: 'minor'
  });

  // Next day
  const hoursUntilTomorrow = 24 - newTime.current_time.hours;
  milestones.push({
    type: 'new_day',
    description: 'Beginning of new day',
    time_until: `${hoursUntilTomorrow} hours`,
    impact_level: 'minor'
  });

  // Next week
  const daysUntilWeek = 7 - (newTime.day_of_week % 7);
  milestones.push({
    type: 'new_week',
    description: 'Beginning of new week',
    time_until: `${daysUntilWeek} days`,
    impact_level: 'minor'
  });

  // Next season (simplified)
  const seasons = ['spring', 'summer', 'autumn', 'winter'];
  const currentSeasonIndex = seasons.indexOf(newTime.current_season);
  const nextSeasonIndex = (currentSeasonIndex + 1) % 4;
  const daysUntilSeason = getDaysUntilNextSeason(newTime.current_season, newTime.current_date);

  milestones.push({
    type: 'seasonal_transition',
    description: `Transition to ${seasons[nextSeasonIndex]}`,
    time_until: `${daysUntilSeason} days`,
    impact_level: 'major'
  });

  return milestones.sort((a, b) => {
    const aHours = parseTimeUntil(a.time_until);
    const bHours = parseTimeUntil(b.time_until);
    return aHours - bHours;
  });
}

function getNextTimeOfDay(currentTimeOfDay) {
  const sequence = ['morning', 'afternoon', 'evening', 'night'];
  const currentIndex = sequence.indexOf(currentTimeOfDay);
  return sequence[(currentIndex + 1) % 4];
}

function getHoursUntilNextTimeOfDay(currentHour, currentTimeOfDay) {
  const transitions = {
    'morning': 12, // noon
    'afternoon': 17, // 5 PM
    'evening': 21, // 9 PM
    'night': 6 // 6 AM (next day)
  };

  const nextHour = transitions[currentTimeOfDay];
  if (nextHour > currentHour) {
    return nextHour - currentHour;
  } else {
    return (24 - currentHour) + nextHour;
  }
}

function getDaysUntilNextSeason(currentSeason, currentDate) {
  const seasonStarts = {
    'spring': 2, // March
    'summer': 5, // June
    'autumn': 8, // September
    'winter': 11 // December
  };

  const currentMonth = currentDate.getMonth();
  const nextSeasonStart = seasonStarts[currentSeason];

  if (nextSeasonStart > currentMonth) {
    return nextSeasonStart - currentMonth;
  } else {
    return (12 - currentMonth) + nextSeasonStart;
  }
}

function parseTimeUntil(timeString) {
  const match = timeString.match(/(\d+)/);
  return match ? parseInt(match[1]) : Infinity;
}

return [{
  json: {
    campaignId: timeData.campaignId,
    time_advancement: timeData.time_advancement,
    enriched_events: enrichedEvents,
    enriched_atmospheric_events: enrichedAtmosphericEvents,
    time_state_updates: timeStateUpdates,
    time_summary: timeSummary,
    player_notifications: timeData.player_notifications,
    time_consequences: timeData.time_consequences,
    narrative_data: narrativeData,
    timestamp: new Date().toISOString(),
    processed_by: 'seasonal-time-system'
  }
}];

// Generate final time advancement response
const timeData = $input.first().json;

const response = {
  success: true,
  advancement_id: timeData.time_summary.time_advancement_id,
  campaign_id: timeData.campaignId,
  time_changes: {
    old_time: timeData.time_summary.time_changes.old_time,
    new_time: timeData.time_summary.time_changes.new_time,
    advancement: timeData.time_summary.time_changes.advancement
  },
  narrative_summary: timeData.time_summary.narrative_summary.literary_description,
  events_processed: timeData.time_summary.events_summary.total_events,
  major_events: timeData.time_summary.events_summary.major_events,
  seasonal_changes: timeData.time_summary.events_summary.seasonal_transitions > 0,
  player_notifications: timeData.time_summary.player_impact.notifications,
  actionable_events: timeData.time_summary.player_impact.actionable_events,
  adventure_opportunities: timeData.time_summary.player_impact.adventure_opportunities,
  next_milestones: timeData.time_summary.next_time_milestones,
  world_state_impact: timeData.time_summary.world_state_impact,
  timestamp: timeData.timestamp
};

return [{ json: response }];
